import {
  Group,
  Mesh,
  Shape,
  ShapeGeometry,
  MeshPhysicalNodeMaterial,
  Vector2
} from 'three/webgpu';
import {
  uv,
  vec3,
  mix,
  step,
  positionWorld,
  cameraPosition,
  normalize,
  dot,
  uniform,
  color
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Geometry: rounded rectangle (capsule shape) ---
  const w = 1.6;   // match atlas aspect ratio 512/320 ≈ 1.6
  const h = 1.0;
  const r = 0.2;   // corner radius

  const shape = new Shape();
  shape.moveTo(0, 0);
  shape.lineTo(0, h);
  shape.quadraticCurveTo(0, h + r, r, h + r);
  shape.lineTo(w - r, h + r);
  shape.quadraticCurveTo(w, h + r, w, h);
  shape.lineTo(w, 0);
  shape.quadraticCurveTo(w, -r, w - r, -r);
  shape.lineTo(r, -r);
  shape.quadraticCurveTo(0, -r, 0, 0);
  shape.closePath();

  // Center the shape at origin
  shape.translate(-w / 2, -h / 2);

  const geometry = new ShapeGeometry(shape);

  // --- Material with edge glow (accent rim light) ---
  const accentColor = color('#ff2a38');
  const surfaceColor = color('#0b0b10');

  // Edge detection using UV – border band of ~0.05 in UV space
  const uvNode = uv();
  const border = 0.05;
  const edgeMask = step(uvNode.x, border)
    .add(step(1.0 - border, uvNode.x))
    .add(step(uvNode.y, border))
    .add(step(1.0 - border, uvNode.y));
  // Clamp to 0..1
  const edgeMaskClamped = mix(0.0, 1.0, step(0.0, edgeMask));

  // Emissive: accent color on edges, black elsewhere
  const emissiveNode = mix(vec3(0.0), accentColor, edgeMaskClamped);

  const material = new MeshPhysicalNodeMaterial();
  material.colorNode = surfaceColor;
  material.emissiveNode = emissiveNode;
  material.emissiveIntensity = 1.2; // controlled glow
  material.metalness = 0.35;
  material.roughness = 0.6;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.3;

  // --- Texture (ceramic grain) ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // --- Interaction handlers ---
  const handlers = {};

  let hoverTween = null;
  let clickTween = null;

  handlers.hover = {
    enter: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, {
        y: 0.15,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    leave: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, {
        y: 0,
        duration: 0.3,
        ease: 'power2.out'
      });
    }
  };

  handlers.click = {
    down: () => {
      if (clickTween) clickTween.kill();
      clickTween = gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.5)',
        onComplete: () => {
          gsap.to(mesh.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.3,
            ease: 'power2.out'
          });
        }
      });
      ctx.emit('hub-pricing.select', {});
    }
  };

  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill GSAP tweens
    if (hoverTween) hoverTween.kill();
    if (clickTween) clickTween.kill();
    // Dispose geometry
    geometry.dispose();
    // Dispose material
    material.dispose();
    // Dispose texture if loaded
    if (material.map) material.map.dispose();
  };

  return group;
}
